% abs begin in 1998
% abs 2002-10-03 to 2004-01-01 --> to invalidate

P4=timerange('1997-01-01','1998-01-01');
BND_tr.BaG0_A11(P4)=NaN;
BND_tr.BaG1_A11(P4)=NaN;

P5=timerange('2002-10-03','2004-01-01');
BND_tr.BaG0_A11(P4)=NaN;
BND_tr.BaG1_A11(P4)=NaN;
%ExpA: only since 2008
P3=timerange('1997-01-01','2008-01-01');
